def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    if not s:
        return 0
    partes = s.split()
    if len(partes) == 1:
        return int(partes[0])
    elif len(partes) == 2:
        horas = int(partes[0])
        minutos = int(partes[1])
        return horas * 60 + minutos
    else:
        return 0

def es_palindromo(s):
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def aplanar(lista):
    result = []
    for item in lista:
        if isinstance(item, list):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    diccionario = {}
    for item in items:
        if item[clave] not in diccionario:
            diccionario[item[clave]] = []
        diccionario[item[clave]].append(item)
    return diccionario

def contar_palabras(texto):
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    diccionario = {}
    for palabra in palabras:
        if palabra not in diccionario:
            diccionario[palabra] = 0
        diccionario[palabra] += 1
    return diccionario

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    numerales = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = []
    for i, (valor, numeral) in enumerate(valores):
        while n >= valor:
            resultado.append(numerales[i])
            n -= valor

    return "".join(resultado)

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    result = 0
    prev = 0
    for char in reversed(s):
        if char in roman_map:
            value = roman_map[char]
            if prev and value < prev:
                result -= value
            else:
                result += value
            prev = value
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 0
    max_element = None

    current_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == current_element:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = current_element
            current_element = lista[i]
            current_racha = 1

    # Verificar la racha final
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = current_element

    return (max_element, max_racha)

def a_camel(s):
    words = s.split()
    result = []
    for word in words:
        if word == words[0]:
            result.append(word.lower())
        else:
            result.append(word[0].upper() + word[1:].lower())
    return ''.join(result)

def a_snake(s):
    if not s:
        return ""
    result = []
    prev_is_upper = False
    for char in s:
        if char.isupper():
            if prev_is_upper:
                result.append("-")
            result.append(char.lower())
            prev_is_upper = False
        else:
            result.append(char.lower())
            prev_is_upper = char.isupper()
    return "".join(result)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

