def comprimir(s):
    if not s:
        return s

    # Contar frecuencias de cada caracter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la cadena comprimida
    compressed = []
    for char, count in counts.items():
        if count > 1:
            compressed.append(f"{char}{count}")

    compressed_str = "".join(compressed)

    # Verificar si la versión comprimida es más corta
    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

def balanceado(texto):
    if not texto:
        return True
    stack = []
    for char in texto:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and char == ')') or \
               (top == '[' and char == ']') or \
               (top == '{' and char == '}'):
                continue
            else:
                return False
    return len(stack) == 0

