def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
    return count

def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

    return dp[m][n]

import re

def validar_password(p):
    if len(p) < 8:
        return False
    if not re.search(r'[A-Z]', p):
        return False
    if not re.search(r'[a-z]', p):
        return False
    if not re.search(r'\d', p):
        return False
    if not re.search(r'[^A-Za-z0-9]', p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n //= base
    return result

def pares_primero(nums):
    pares = []
    impares = []
    for num in nums:
        if num % 2 == 0:
            pares.append(num)
        else:
            impares.append(num)
    return pares + impares

from datetime import datetime

def dias_entre(a, b):
    fecha_a = datetime.strptime(a, '%Y-%m-%d')
    fecha_b = datetime.strptime(b, '%Y-%m-%d')
    return abs((fecha_b - fecha_a).days)

