def titular(s):
    palabras = s.split()
    resultado = []
    for i, palabra in enumerate(palabras):
        if palabra in ['de', 'del', 'la', 'las', 'el', 'los', 'y']:
            if i == 0:
                resultado.append(palabra.lower())
            else:
                resultado.append(palabra)
        else:
            resultado.append(palabra.capitalize())
    return ' '.join(resultado)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    if not isinstance(lista, list):
        raise TypeError("La lista debe ser de tipo list")

    if not isinstance(lista[0], list):
        raise ValueError("La lista debe estar anidada")

    return [aplanar_hasta(item, profundidad - 1) for item in lista]

def obtener(d, camino, defecto=None):
    if not isinstance(camino, str):
        raise TypeError("El camino debe ser una cadena")

    partes = camino.split('.')
    valor = d

    for parte in partes:
        if valor is None:
            return defecto
        if parte not in valor:
            return defecto
        valor = valor[parte]

    return valor

def con_reintentos(fn, veces):
    for i in range(veces):
        try:
            return fn()
        except Exception:
            if i < veces - 1:
                continue
            raise
    raise RuntimeError("Todos los intentos fallaron")
